const source = $input.first().json;
const config = $('Configurar prueba T-78').first().json;
const inputs = JSON.parse(JSON.stringify(source));

inputs.geometry = {
  ...(inputs.geometry ?? {}),
  nominal_diameter_m: Number(config.diametroNominalM),
  design_liquid_height_m: Number(config.alturaLiquidoM),
};
inputs.product = {
  ...(inputs.product ?? {}),
  specific_gravity: Number(config.gravedadEspecifica),
};
inputs.seismic = {
  ...(inputs.seismic ?? {}),
  Sp: Number(config.aceleracionPicoG),
};

return [{
  json: {
    nombreVariante: config.nombreVariante,
    inputs,
  },
}];

const data = $input.first().json;
let pregunta = 'Genera un resumen tecnico breve de los datos de entrada y resultados, e identifica los valores que requieren mayor atencion.';

try {
  const chat = $('Conversar sobre resultados').first().json;
  if (chat?.chatInput) pregunta = String(chat.chatInput);
} catch (_error) {
  // La ejecucion manual no activa el Chat Trigger; se conserva la pregunta predeterminada.
}

const inputsCalculados = $('Aplicar variantes').first().json.inputs ?? {};
const resultado = data.resultadoCompleto ?? {};
const modulos = {};

for (const [nombre, modulo] of Object.entries(resultado.modules ?? {})) {
  modulos[nombre] = {
    status: modulo.status,
    values: modulo.values,
    checks: modulo.checks,
  };
}

const contextoCalculo = {
  metadata: {
    engine_version: resultado.engine_version ?? data.versionMotor,
    standard_profile: resultado.standard_profile,
    overall_status: resultado.overall_status ?? data.estadoGlobal,
    input_sha256: resultado.input_sha256 ?? data.huellaEntradas,
  },
  inputs: inputsCalculados,
  summary: resultado.summary ?? {},
  modules: modulos,
};

const systemPrompt = [
  'Actua como un asistente de ingenieria estructural especializado en tanques de almacenamiento y API 650.',
  'Responde exclusivamente usando los datos de entrada y los resultados de la simulacion proporcionada.',
  'Distingue claramente entre dato de entrada, valor derivado, resultado calculado y verificacion PASS, FAIL o WARNING.',
  'Puedes explicar relaciones tecnicas entre entradas y resultados, pero no afirmes causalidad que no este respaldada por el contexto.',
  'No inventes valores, no uses informacion externa, no modifiques resultados ni afirmes que el diseno esta certificado.',
  'Si una pregunta no puede responderse con el contexto recibido, indica exactamente que informacion falta.',
  'Responde en espanol, conserva las unidades y utiliza lenguaje tecnico claro.',
].join(' ');

const chatInput = [
  'Pregunta del usuario:',
  pregunta,
  '',
  'Contexto de la simulacion en formato JSON:',
  JSON.stringify(contextoCalculo, null, 2),
].join('\n');

return [{
  json: {
    ...data,
    preguntaUsuario: pregunta,
    contextoCalculo,
    chatInput,
    deepSeekRequest: {
      model: 'deepseek-flash',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: chatInput },
      ],
      thinking: { type: 'disabled' },
      max_tokens: 2500,
      stream: false,
    },
  },
}];
